// The INTEGRATION node projection (`an-integration-is-a-glance-node-with-a-real-signal`) — turn the two
// landed reads into Glance nodes and edges.
//
// The inputs are the DEMAND and the SUPPLY, and joining them is the whole design:
//
//   demand  `bsc project integrations`      — which projects DECLARED which integrations, at Discovery.
//   supply  `bsc data connector status`     — whether a registered connector last verified, and against
//                                             which manifest.
//
// This module is the PURE projection of that join into the graph vocabulary; fetching is the caller's
// job, exactly as `surfaceNodes` does it.
//
// WHY THIS BAND MAY RENDER WHERE THE SURFACE BAND WAS REVERTED. The surface nodes were hardcoded
// `health: "off"` / `activity: "idle"` — inert by construction, so a cockpit gained 34 marks that could
// never change state. An integration's dot is DERIVED from a real verdict, and every one of its states
// is reachable by ordinary work: declared-but-unbuilt → built-but-unverified → live → stale the moment
// a manifest is edited → failing. It shows work moving, which is the property the revert demanded.
import {
  integrationNodeId,
  usesIntegrationEdgeId,
  type GRawNode,
  type GRawEdge,
  type GHealth,
} from "@/features/glance/lib/glanceGraph";

/** One row of `bsc project integrations` — a project's DECLARED integration. */
export interface DeclaredIntegrationRow {
  /** The project key that declared it. */
  project: string;
  /** The declared slug — the join key to a connector of the same id. */
  id: string;
  /** Display name, when it differs from the id. */
  name?: string;
  /** `source` (data migrates FROM it) | `runtime` (the app talks to it while running). */
  direction?: string;
}

/** The verdict states `bsc data connector status` reports, mirroring `CheckState` in `crates/data`. */
export type IntegrationCheckState = "never-checked" | "live" | "failing" | "stale";

/** One row of `bsc data connector status` — a REGISTERED connector and its last verdict. */
export interface ConnectorStatusRow {
  id: string;
  state: IntegrationCheckState;
  /** The failure reason, when the last check failed. */
  error?: string | null;
}

/** The projected band: one node per integration, one edge per declaration. */
export interface IntegrationGraph {
  nodes: GRawNode[];
  edges: GRawEdge[];
}

/**
 * The node health for one integration, derived from whether it is BUILT and what it last verified.
 *
 * `off` is not `healthy`, and that distinction is the whole reason this function exists rather than a
 * ternary at the call site. A connector nobody has checked has earned neither green nor red — the dot
 * is supposed to mean something, and asserting health nobody measured is what made the surface band
 * worth reverting.
 *
 * An integration that is DECLARED but has no connector is also `off`, and that is not a defect: it is
 * the Integrator's queue, rendered. Wanted, not yet built.
 */
export function integrationHealth(state: IntegrationCheckState | undefined): GHealth {
  switch (state) {
    case "live":
      return "healthy";
    case "failing":
      return "error";
    // A verdict about a manifest that has since changed says nothing about the current shape. It is a
    // warning rather than an error because nothing is known to be BROKEN — it is known to be unverified,
    // which is a different and softer claim.
    case "stale":
      return "warning";
    default:
      return "off";
  }
}

/**
 * Project declared integrations + connector verdicts into integration nodes and project edges.
 *
 * EVERY INTEGRATION THAT EXISTS GETS A NODE — declared, registered, or both. A connector registered
 * app-wide that no project declared is still real and still needs an owner, so it appears with no
 * edges rather than being hidden. That is the maintainer's decision and it is the opposite of the MCP
 * band's rule, where a globally-scoped server is skipped.
 *
 * An edge to a project NOT in `projectKeys` is DROPPED. A dangling edge is worse than a missing one:
 * the layout would carry a node id nothing renders. When `projectKeys` is undefined the caller is
 * saying it does not know the project set, and every declared edge is kept.
 */
export function integrationGraph(
  declared: DeclaredIntegrationRow[],
  connectors: ConnectorStatusRow[] = [],
  projectKeys?: Iterable<string>,
): IntegrationGraph {
  const known = projectKeys ? new Set(projectKeys) : null;
  const statusById = new Map(connectors.map((c) => [c.id, c]));

  // The node set is the UNION of both sides, in a stable order: declaration order first (that is the
  // order a reader met them in), then any registered connector nobody declared.
  const ids: string[] = [];
  const seen = new Set<string>();
  for (const d of declared) {
    if (d.id && !seen.has(d.id)) {
      seen.add(d.id);
      ids.push(d.id);
    }
  }
  for (const c of connectors) {
    if (c.id && !seen.has(c.id)) {
      seen.add(c.id);
      ids.push(c.id);
    }
  }

  const nameById = new Map<string, string>();
  for (const d of declared) {
    if (d.name && !nameById.has(d.id)) nameById.set(d.id, d.name);
  }

  const nodes: GRawNode[] = ids.map((id) => {
    const status = statusById.get(id);
    const health = integrationHealth(status?.state);
    return {
      id: integrationNodeId(id),
      slug: nameById.get(id) || id,
      kind: "integration" as const,
      role: "infra" as const,
      health,
      // `idle` always: an integration is a system we READ on demand, never something that is "building".
      activity: "idle" as const,
      // The reason is carried ONLY when the dot changed, matching every other band node — a reason
      // beside a healthy dot reads as a problem that is not there.
      ...(health === "error" && status?.error ? { reason: status.error } : {}),
    };
  });

  const edges: GRawEdge[] = [];
  const drawn = new Set<string>();
  for (const d of declared) {
    if (!d.id || !d.project) continue;
    if (known && !known.has(d.project)) continue;
    const id = usesIntegrationEdgeId(d.project, d.id);
    if (drawn.has(id)) continue;
    drawn.add(id);
    edges.push({ id, from: d.project, to: integrationNodeId(d.id), kind: "uses-integration" });
  }
  return { nodes, edges };
}

/** How many projects declared `id` — the number that says how much a broken integration reaches. */
export function declaringProjectCount(declared: DeclaredIntegrationRow[], id: string): number {
  return new Set(declared.filter((d) => d.id === id).map((d) => d.project)).size;
}
